/**
 * HEAVIX — STEP 14.8: Production Readiness Gate
 *
 * A programmatic gate that enumerates every checkpoint required to declare
 * the platform production-ready. Each checkpoint has a status and evidence
 * pointer (test name, doc path, or code path).
 *
 * The gate is PASS when ALL CRITICAL checkpoints are PASS and no HIGH-risk
 * items are PENDING. Non-critical items may remain PENDING at launch.
 *
 * V2.4 — Generated by STEP 14.8.
 */

export type GateStatus = 'PASS' | 'PENDING' | 'FAIL' | 'N/A';
export type GateSeverity = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';

export interface GateCheck {
  id: string;
  category: 'Schema' | 'RBAC' | 'Audit' | 'PageBuilder' | 'CRUD' | 'E2E' | 'Performance' | 'Security' | 'Documentation' | 'Migration';
  title: string;
  severity: GateSeverity;
  status: GateStatus;
  evidence: string; // test name, file path, or doc reference
  notes?: string;
}

